import {uid} from './model.js';
import {importSIQ,exportSIQ} from './siq.js';
import {emptyMergePack,addMergeItem,mergeIssues,mergeMedia} from './merge-model.js';
import {getMergeDraft,saveMergeDraft} from './storage.js';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const b=(action,label,attrs='')=>`<button type="button" data-merge="${action}" ${attrs}>${label}</button>`;
const count=(n,forms)=>`${n} ${forms[n%100>=11&&n%100<=14?2:n%10===1?0:n%10>=2&&n%10<=4?1:2]}`;
const stats=p=>[count(p.rounds.length,['раунд','раунда','раундов']),count(p.rounds.reduce((n,r)=>n+r.themes.length,0),['тема','темы','тем']),count(p.rounds.reduce((n,r)=>n+r.themes.reduce((m,t)=>m+t.questions.length,0),0),['вопрос','вопроса','вопросов'])].join(' · ');
export function createMerger({root,onHome,toast}){
 let state={sources:[null,null],pack:emptyMergePack(),media:new Map(),stage:0},active,history=[],future=[],busy=false,loaded=false,saveQueue=Promise.resolve(),pending=0,unsaved=false,drag=null,saveTimer,dirty=false,editOwner=null;
 const saveStatus=()=>{const el=root.querySelector('#merge-save-status');if(el)el.textContent=unsaved?'Не сохранено · скачайте .siq':pending||dirty?'Сохраняем сборку…':'Сборка сохранена на устройстве';};
 const persistState=()=>{const value=structuredClone(state);pending++;saveStatus();saveQueue=saveQueue.catch(()=>{}).then(()=>saveMergeDraft(value)).then(()=>{unsaved=false;},()=>{unsaved=true;toast('Сборка не сохранена. Скачайте .siq перед закрытием.');}).finally(()=>{pending--;saveStatus();});};
 const save=()=>{dirty=true;clearTimeout(saveTimer);saveStatus();saveTimer=setTimeout(()=>{dirty=false;persistState();},300);};
 const flushSave=()=>{clearTimeout(saveTimer);if(dirty){dirty=false;persistState();}return saveQueue;};
 const record=()=>{history.push({pack:structuredClone(state.pack),active});if(history.length>30)history.shift();future=[];};
 const finish=()=>{save();render();};
 const round=()=>state.pack.rounds.find(r=>r.id===active)||state.pack.rounds[0];
 function sourceHTML(source,side){return `<section class="merge-pane merge-source" data-side="${side}"><header><span class="merge-eyebrow">${side===0?'ЛЕВЫЙ ПАК':'ПРАВЫЙ ПАК'}</span><h2>${source?e(source.pack.name):'Загрузите пак'}</h2><p>${source?stats(source.pack):'Файл .siq с вашего устройства'}</p>${b('load',source?'Заменить .siq':'Выбрать .siq',`data-side="${side}" class="secondary" ${busy?'disabled':''}`)}</header><div class="merge-scroll">${source?source.pack.rounds.map((r,ri)=>`<details class="merge-source-round" data-key="${r.id}" open><summary>${e(r.name)}${r.type==='final'?' · Финал':''}</summary>${state.stage?`<div class="merge-transfer" draggable="true" data-side="${side}" data-ri="${ri}"><span>⠿ Весь раунд</span>${b('copy','Добавить →',`data-side="${side}" data-ri="${ri}" aria-label="Добавить раунд ${e(r.name)}"`)}</div>`:''}${r.themes.map((t,ti)=>`<details class="merge-source-theme" data-key="${t.id}"><summary><span>${e(t.name)}<small>${t.questions.length} вопросов</small></span></summary>${state.stage?`<div class="merge-transfer" draggable="true" data-side="${side}" data-ri="${ri}" data-ti="${ti}"><span>⠿ Эта тема</span>${b('copy','Добавить →',`data-side="${side}" data-ri="${ri}" data-ti="${ti}" aria-label="Добавить тему ${e(t.name)}"`)}</div>`:''}<ol>${t.questions.map(q=>`<li><strong>${r.type==='final'?'Финал':q.price}</strong> ${e(q.steps.find(s=>s.type==='text')?.value||'Медиавопрос')}<small>Ответ: ${e(q.answer)}</small></li>`).join('')}</ol></details>`).join('')}</details>`).join(''):'<div class="merge-upload-hint"><span>↑</span><p>Перетащите сюда .siq<br>или выберите файл</p></div>'}</div></section>`;}
 function centerHTML(){const r=round();return `<section class="merge-pane merge-result"><header><span class="merge-eyebrow">ОБЩИЙ ПАК</span><label>Название пака<input data-merge-name="pack" value="${e(state.pack.name)}" maxlength="200"></label><details class="merge-authors" data-key="authors"><summary>Авторы пака</summary><label>Авторы<input data-merge-name="author" value="${e(state.pack.author)}" placeholder="Авторы исходных паков"></label></details><p>${stats(state.pack)}</p><div class="merge-history">${b('undo','↶ Отменить',history.length?'':'disabled')}${b('redo','↷ Повторить',future.length?'':'disabled')}</div></header><div class="merge-result-tools">${b('new-round','+ Раунд')}${!state.pack.rounds.some(x=>x.type==='final')?b('new-final','+ Финал'):''}</div><div class="merge-round-tabs">${state.pack.rounds.map(rr=>b('select',e(rr.name),`data-id="${rr.id}" ${rr.id===r?.id?'aria-current="true"':''}`)).join('')}</div><div class="merge-scroll merge-drop" data-drop="true" data-round="${r?.id||''}">${r?`<div class="merge-target-heading"><label>Раунд${r.type==='final'?' · Финал':''}<input data-merge-name="round" value="${e(r.name)}" maxlength="200"></label><div>${b('round-up','↑',`aria-label="Раунд раньше" ${state.pack.rounds.indexOf(r)<=0||r.type==='final'?'disabled':''}`)}${b('round-down','↓',`aria-label="Раунд позже" ${state.pack.rounds.indexOf(r)>=state.pack.rounds.length-1||state.pack.rounds[state.pack.rounds.indexOf(r)+1]?.type==='final'?'disabled':''}`)}${b('remove-round','Удалить')}</div></div>${r.themes.map((t,i)=>`<article class="merge-result-theme"><label>Тема<input data-merge-theme="${t.id}" value="${e(t.name)}" maxlength="200"></label><p>${t.questions.length?`${t.questions.length} вопросов · ${t.questions.map(q=>r.type==='final'?'Финал':q.price).join(' / ')}`:'Место для первой темы'}</p><div>${b('theme-up','↑',`data-id="${t.id}" aria-label="Тему выше" ${i===0?'disabled':''}`)}${b('theme-down','↓',`data-id="${t.id}" aria-label="Тему ниже" ${i===r.themes.length-1?'disabled':''}`)}${b('remove-theme','Убрать',`data-id="${t.id}"`)}</div></article>`).join('')}<p class="merge-drop-hint">Перетащите сюда раунд или тему.<br>Темы добавляются в выбранный раунд.</p>`:'<p class="merge-drop-hint">Добавьте раунд из исходного пака<br>или создайте пустой.</p>'}</div><footer>${b('export','↓ Экспорт .siq',`class="primary" ${busy?'disabled':''}`)}<span id="merge-save-status" role="status">Сборка сохранена на устройстве</span></footer></section>`;}
 function render(){const scrolls=[...root.querySelectorAll('.merge-scroll,.merge-round-tabs')].map(el=>[el,el.scrollTop,el.scrollLeft]),details=new Map([...root.querySelectorAll('details[data-key]')].map(el=>[el.dataset.key,el.open]));root.innerHTML=`<div class="merge-shell"><header class="merge-header"><a class="brand" href="./" data-merge="home"><img class="brand-logo" src="./assets/logo-horizontal.png" alt="SIGameMaker"></a><div><h1>Объединение паков</h1><p>${state.stage?'2. Соберите общий пак → 3. Экспортируйте .siq':'1. Загрузите два пака → 2. Соберите общий'}</p></div>${b('home','В меню','class="secondary"')}</header><main class="merge-workspace ${state.stage?'':'merge-loading'}">${sourceHTML(state.sources[0],0)}${state.stage?centerHTML():`<section class="merge-start"><span>＋</span><h2>Два пака.<br>Одна новая игра.</h2><p>Выберите нужные раунды и темы на следующем шаге.</p>${state.sources.every(Boolean)?b('start','Объединить','class="primary"'):''}<small>Исходные паки и черновик редактора сохраняются отдельно.</small></section>`}${sourceHTML(state.sources[1],1)}</main><input type="file" id="merge-file" accept=".siq" hidden></div>`;const next=[...root.querySelectorAll('.merge-scroll,.merge-round-tabs')];scrolls.forEach(([old,top,left],i)=>{if(next[i]&&old.dataset.round===next[i].dataset.round){next[i].scrollTop=top;next[i].scrollLeft=left;}});for(const el of root.querySelectorAll('details[data-key]'))if(details.has(el.dataset.key))el.open=details.get(el.dataset.key);saveStatus();}
 async function load(file,side){if(busy||!file)return;if(!/\.siq$/i.test(file.name)){toast('Выберите файл .siq');return;}if(file.size>250*1024*1024){toast('Пак больше 250 МБ');return;}busy=true;render();try{const result=importSIQ(new Uint8Array(await file.arrayBuffer()));state.sources[side]=result;save();toast('Пак загружен'+(result.repairs?.length?' · применены обычные правила финала':''));}catch(err){toast('Не удалось загрузить пак. '+err.message);const box=document.createElement('dialog');box.className='merge-error';const title=document.createElement('h2');title.textContent='Пак не загружен';const text=document.createElement('pre');text.textContent=err.message;const close=document.createElement('button');close.textContent='Закрыть';close.onclick=()=>box.close();box.append(title,text,close);document.body.append(box);box.addEventListener('close',()=>box.remove(),{once:true});box.showModal();}finally{busy=false;render();}}
 function copy(data){const side=Number(data.side),ri=Number(data.ri),ti=data.ti===undefined?null:Number(data.ti);const next=structuredClone(state.pack),files=new Map(state.media);try{const id=addMergeItem(next,files,state.sources[side],ri,ti,round()?.id);record();state.pack=next;state.media=files;active=id;finish();toast(ti===null?'Раунд добавлен':'Тема добавлена');}catch(err){toast(err.message);}}
 root.addEventListener('click',async ev=>{const el=ev.target.closest('[data-merge]');if(!el||el.disabled)return;ev.preventDefault();const action=el.dataset.merge;if(action==='home'){await flushSave();onHome();return;}if(action==='load'){const input=root.querySelector('#merge-file');input.onchange=()=>load(input.files[0],Number(el.dataset.side));input.click();return;}if(action==='start'){state.stage=1;if(!state.pack.author)state.pack.author=[...new Set(state.sources.map(s=>s.pack.author).filter(Boolean))].join(', ');finish();return;}if(action==='select'){active=el.dataset.id;render();return;}if(action==='copy'){copy(el.dataset);return;}if(action==='undo'||action==='redo'){const from=action==='undo'?history:future,to=action==='undo'?future:history;if(!from.length)return;to.push({pack:structuredClone(state.pack),active});const old=from.pop();state.pack=old.pack;active=old.active;finish();return;}if(action==='export'){const errors=mergeIssues(state.pack,state.media);if(errors.length){const box=document.createElement('dialog');box.className='merge-error';box.innerHTML=`<h2>Перед экспортом</h2><p>Исправьте замечания. Вопросы можно доработать в основном редакторе исходного пака и загрузить его заново.</p><ul>${errors.map(x=>`<li>${e(x.message)}</li>`).join('')}</ul><button>Закрыть</button>`;box.querySelector('button').onclick=()=>box.close();document.body.append(box);box.onclose=()=>box.remove();box.showModal();return;}busy=true;render();try{const bytes=await exportSIQ(state.pack,state.media),url=URL.createObjectURL(new Blob([bytes],{type:'application/zip'})),a=document.createElement('a');a.href=url;a.download=(state.pack.name.replace(/[\\/:*?"<>|]/g,'_')||'Общий пак')+'.siq';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Общий пак .siq готов');}catch(err){toast(err.message);}finally{busy=false;render();}return;}record();const r=round(),themes=r?.themes,i=themes?.findIndex(t=>t.id===el.dataset.id),ri=state.pack.rounds.indexOf(r);if(action==='new-round'||action==='new-final'){const next={id:uid(),name:action==='new-final'?'Финал':`Раунд ${state.pack.rounds.length+1}`,type:action==='new-final'?'final':'standard',themes:[]};const fi=state.pack.rounds.findIndex(x=>x.type==='final');state.pack.rounds.splice(fi<0?state.pack.rounds.length:fi,0,next);active=next.id;}else if(action==='remove-round')state.pack.rounds.splice(ri,1);else if(action==='remove-theme')themes.splice(i,1);else if(action==='theme-up'||action==='theme-down'){const j=i+(action==='theme-up'?-1:1);[themes[i],themes[j]]=[themes[j],themes[i]];}else if(action==='round-up'||action==='round-down'){const j=ri+(action==='round-up'?-1:1);[state.pack.rounds[ri],state.pack.rounds[j]]=[state.pack.rounds[j],state.pack.rounds[ri]];}finish();});
 root.addEventListener('focusout',()=>{editOwner=null;});
 root.addEventListener('input',ev=>{const el=ev.target;if(!el.matches('[data-merge-name],[data-merge-theme]'))return;if(editOwner!==el){record();editOwner=el;const undo=root.querySelector('[data-merge=undo]'),redo=root.querySelector('[data-merge=redo]');if(undo)undo.disabled=false;if(redo)redo.disabled=true;}const field=el.dataset.mergeName;if(field==='pack')state.pack.name=el.value;else if(field==='author')state.pack.author=el.value;else if(field==='round')round().name=el.value;else round().themes.find(t=>t.id===el.dataset.mergeTheme).name=el.value;save();});
 root.addEventListener('dragstart',ev=>{const item=ev.target.closest('.merge-transfer');if(!item)return;drag={...item.dataset};ev.dataTransfer.effectAllowed='copy';ev.dataTransfer.setData('text/plain','SI Studio');});
 root.addEventListener('dragend',()=>{drag=null;root.querySelectorAll('.merge-hover').forEach(x=>x.classList.remove('merge-hover'));});
 root.addEventListener('dragover',ev=>{const area=ev.target.closest('[data-drop],.merge-source');if(!area)return;ev.preventDefault();ev.dataTransfer.dropEffect='copy';area.classList.add('merge-hover');if(area.matches('[data-drop]')){const rect=area.getBoundingClientRect();if(ev.clientY<rect.top+45)area.scrollTop-=15;if(ev.clientY>rect.bottom-45)area.scrollTop+=15;}});
 root.addEventListener('dragleave',ev=>{const area=ev.target.closest('.merge-hover');if(area&&!area.contains(ev.relatedTarget))area.classList.remove('merge-hover');});
 root.addEventListener('drop',ev=>{const area=ev.target.closest('[data-drop],.merge-source');if(!area)return;ev.preventDefault();area.classList.remove('merge-hover');if(area.dataset.drop&&drag){copy(drag);drag=null;}else if(area.matches('.merge-source')&&ev.dataTransfer.files.length){if(ev.dataTransfer.files.length!==1){toast('Перетащите один .siq в каждую панель');return;}load(ev.dataTransfer.files[0],Number(area.dataset.side));}});
 window.addEventListener('beforeunload',ev=>{if(pending||dirty||unsaved){ev.preventDefault();ev.returnValue='';}});
 return {async open(){if(!loaded){try{const saved=await getMergeDraft();if(saved){state=saved;state.media=mergeMedia(state.pack,state.media);}}catch{toast('Сохранённая сборка недоступна');}loaded=true;}render();}};
}
